<?php
declare(strict_types=1);require_once __DIR__.'/../auth_check.php';require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../services/MeetingDailyFollowupService.php';require_once __DIR__.'/../vendor/autoload.php';require_once __DIR__.'/../model/CompanyPdfTemplate.php';
class MeetingFollowupIsoPdf extends TCPDF{use CompanyPdfTemplate;public function Header():void{$this->drawCompanyPdfHeader();}public function Footer():void{$this->drawCompanyPdfFooter();}}
$uid=(int)($_SESSION['user_id']??0);$rows=(new MeetingDailyFollowupService(Database::getConnection()))->exportRows($uid);$labels=['pending'=>'En attente de réponse','completed'=>'Terminée','rescheduled'=>'Exécution reportée','remind'=>'Rappel demandé','decision_deferred'=>'Décision reportée'];$name=trim((string)($_SESSION['user_name']??($_SESSION['prenom']??'').' '.($_SESSION['nom']??'')))?:'Utilisateur';$doc='FIN-REU-SUIVI-'.date('Ymd-His').'-U'.$uid;
$pdf=new MeetingFollowupIsoPdf('L','mm','A4',true,'UTF-8',false);$pdf->companyPdfTitle='Suivi des engagements de réunion';$pdf->companyPdfType='État quotidien pilote / copilote';$pdf->companyPdfId=$doc;$pdf->companyPdfCode='FIN-REU-SUIVI';$pdf->companyPdfQrPayload=json_encode(['document'=>$doc,'user_id'=>$uid,'count'=>count($rows),'generated_at'=>date(DATE_ATOM)],JSON_UNESCAPED_UNICODE);$pdf->SetCreator('Finéa');$pdf->SetAuthor($name);$pdf->SetTitle('Suivi des engagements de réunion');$pdf->SetMargins(10,38,10);$pdf->SetAutoPageBreak(true,25);$pdf->AddPage();
$pdf->SetFillColor(248,250,252);$pdf->SetDrawColor(226,232,240);$pdf->RoundedRect(10,40,277,18,2,'1111','DF');$pdf->SetXY(14,44);$pdf->SetFont('dejavusans','B',10);$pdf->SetTextColor(15,23,42);$pdf->Cell(150,5,$name,0,0);$pdf->SetFont('dejavusans','',8);$pdf->SetTextColor(71,85,105);$pdf->Cell(119,5,count($rows).' élément(s) de suivi · Généré le '.date('d/m/Y H:i'),0,1,'R');$pdf->SetY(63);
$widths=[17,25,27,28,38,46,15,23,18,14];$headers=['Date','Réunion','Service / Chantier','Rubrique','Point','Sous-tâche','Rôle','Décision','Exécution','Reports'];$drawHeader=function()use($pdf,$widths,$headers){$pdf->SetFillColor(250,189,2);$pdf->SetTextColor(0,0,0);$pdf->SetFont('dejavusans','B',6.7);foreach($headers as$i=>$h)$pdf->Cell($widths[$i],8,$h,1,0,'C',true);$pdf->Ln();};$drawHeader();$pdf->SetFont('dejavusans','',6.4);if(!$rows){$pdf->SetTextColor(71,85,105);$pdf->SetFont('dejavusans','I',9);$pdf->Cell(array_sum($widths),18,'Aucun engagement de réunion ne vous est actuellement attribué.',1,1,'C');}
foreach($rows as$r){
    $pdf->SetFont('dejavusans','',6.4);$execution=(string)($r['execution_date']??'');
    $overdue=$execution!==''&&$execution<date('Y-m-d')&&(string)($r['response_type']??'')!=='completed';
    $decision=$labels[$r['response_type']]??$r['response_type'];if($overdue)$decision='En retard · '.$decision;
    $values=[!empty($r['response_date'])?date('d/m/Y',strtotime((string)$r['response_date'])):'—',$r['meeting_title'],$r['group_label'],$r['section_title'],$r['task_title'],$r['checklist_label'],$r['role_label'],$decision,$execution!==''?date('d/m/Y',strtotime($execution)):'—',(string)(int)$r['reschedule_count']];
    $heights=[];foreach($values as$i=>$v)$heights[]=$pdf->getStringHeight($widths[$i]-2,(string)$v);$h=max(8,min(18,max($heights)+2));
    if($pdf->GetY()+$h>178){$pdf->AddPage();$pdf->SetY(40);$drawHeader();$pdf->SetFont('dejavusans','',6.4);}
    $x=$pdf->GetX();$y=$pdf->GetY();foreach($values as$i=>$v){$pdf->SetXY($x,$y);$pdf->SetFont('dejavusans','',6.4);$lateCell=$overdue&&$i===7;if($lateCell){$pdf->SetFillColor(255,247,247);$pdf->SetTextColor(153,27,27);}elseif($overdue&&$i===8){$pdf->SetFillColor(255,255,255);$pdf->SetTextColor(153,27,27);}else{$pdf->SetFillColor(255,255,255);$pdf->SetTextColor(30,41,59);}$pdf->MultiCell($widths[$i],$h,(string)$v,1,$i===9?'C':'L',$lateCell,0,'','',true,0,false,true,$h,'M');$x+=$widths[$i];}$pdf->SetY($y+$h);
}
while(ob_get_level()>0)ob_end_clean();$pdf->Output('suivi_reunions_'.date('Ymd_His').'.pdf','I');exit;
